    if ":" in run_dir or "," in run_dir:
        raise GradeError("the run directory path must not contain ':' or ','")
    grading = os.path.join(run_dir, "grading")
    fresh_dir(grading)
    a2a = os.path.join(sb, "grimoires", "loa", "a2a", SPRINT)

